            forecast = np.dot(coef, x_last)
            return float(current - forecast)
        except:
            return np.nan

    exprs = [
        pl.col(c).fill_nan(None).rolling_map(_ar_innov, window_size=w+1, min_samples=p+3).alias(c)
        for c in cols
    ]
    return x.with_columns(exprs)

