def _is_panel_like(value: Any) -> bool:
    if isinstance(value, (int, float, str, bool, np.number)) or value is None:
        return False
    columns = getattr(value, "columns", None)
    if columns is None:
        return False
    try:
        return len(list(columns)) > 0
    except TypeError:
        return False

